REQUIRED_FIELDS = ("user_id", "amount")
SUPPORTED_CURRENCIES = ("USD", "EUR", "GBP")


def validate_record(record):
    """Return deterministic local validation errors for one input record."""
    if not isinstance(record, dict):
        return [{"field": "record", "code": "invalid_type", "message": "record must be an object"}]

    errors = []
    for field_name in REQUIRED_FIELDS:
        if field_name not in record or record[field_name] is None:
            errors.append({"field": field_name, "code": "required", "message": "field is required"})

    if "user_id" in record and record["user_id"] is not None:
        if not isinstance(record["user_id"], str) or not record["user_id"].strip():
            errors.append({"field": "user_id", "code": "invalid", "message": "must be a non-empty string"})

    if "amount" in record and record["amount"] is not None:
        if isinstance(record["amount"], bool) or not isinstance(record["amount"], (int, float)):
            errors.append({"field": "amount", "code": "invalid", "message": "must be numeric"})

    if record.get("currency") is not None and record["currency"] not in SUPPORTED_CURRENCIES:
        errors.append({"field": "currency", "code": "invalid", "message": "unsupported currency"})

    return errors

