import json
from pathlib import Path

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS, validate_record as validate_input


def validate_record(record):
    return validate_input(record)


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        profile = {}
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(payload, list):
        raise ValueError("transaction input must be a list")

    # Screen the whole batch before crossing either API boundary.
    failures = []
    accepted = []
    for index, record in enumerate(payload):
        errors = validate_record(record)
        if errors:
            failures.append({"index": index, "record": record, "errors": errors})
        else:
            accepted.append((index, record))

    results = []
    for index, record in accepted:
        try:
            normalized = normalize(enrich(record))
        except (TypeError, ValueError) as exc:
            failures.append({
                "index": index,
                "record": record,
                "errors": [{"field": "currency", "code": "invalid", "message": str(exc)}],
            })
            continue
        results.append(send_transaction(normalized))

    failures.sort(key=lambda failure: failure["index"])
    return {
        "results": results,
        "failures": failures,
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
        "total": len(payload),
        "succeeded": len(results),
        "failed": len(failures),
    }
